#!/usr/bin/env Rscript
# Exact accepted 10/7 panel design, now reading complete newly recomputed loops.
options(stringsAsFactors=FALSE,warn=1)
suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(patchwork);library(jsonlite);library(digest)})
args<-commandArgs(TRUE);m<-if(length(args))normalizePath(args[1])else normalizePath('01_method_definition/ED4fh_full_recompute_20261008')
f<-read.csv(file.path(m,'tables/ED4f_summary.csv'));f$correlation_error_SD<-f$cor_err_se
pf1<-ggplot(f,aes(p,cor_err))+geom_errorbar(aes(ymin=cor_err-correlation_error_SD,ymax=cor_err+correlation_error_SD),width=0)+geom_line(colour='#E64B35FF',linewidth=.7)+geom_point(colour='#E64B35FF',size=2)+scale_x_log10(breaks=f$p,labels=scales::label_number(big.mark=','))+labs(x='Number of features',y='Correlation RMS error')+theme_classic(base_size=12)+theme(axis.text.x=element_text(angle=45,hjust=1))
pf2<-ggplot(f[f$p<500,],aes(p,condnum))+geom_line(colour='#4DBBD5FF',linewidth=.7)+geom_point(colour='#4DBBD5FF',size=2)+scale_x_log10(breaks=f$p,labels=scales::label_number(big.mark=','),limits=range(f$p))+scale_y_log10(labels=scales::label_number(big.mark=','))+labs(x='Number of features',y='Covariance condition number')+theme_classic(base_size=12)+theme(axis.text.x=element_text(angle=45,hjust=1))
ggsave(file.path(m,'figures/ED4f_FULL_LOOP_DIAGNOSTIC.pdf'),pf1+pf2+plot_annotation(tag_levels='a'),width=9,height=3.8,device='pdf')
d<-read.csv(file.path(m,'tables/ED4h_DISCO_2100.csv'));dm<-read.csv(file.path(m,'tables/ED4h_DM_700.csv'))
ds<-d%>%group_by(weight,model,refsize)%>%summarise(mean=mean(ci),SD=sd(ci),n_rep=n(),.groups='drop');ms<-dm%>%group_by(model,refsize)%>%summarise(mean=mean(ci),SD=sd(ci),n_rep=n(),.groups='drop');stopifnot(all(ds$n_rep==50),all(ms$n_rep==50))
models<-c('crude','age+sex','accel');cols<-c('crude'='#E64B35FF','age+sex'='#4DBBD5FF','accel'='#00A087FF');refsizes<-sort(unique(d$refsize))
ph1<-ggplot(ds,aes(refsize,mean,colour=model,fill=model,linetype=weight,group=interaction(model,weight)))+geom_ribbon(aes(ymin=mean-SD,ymax=mean+SD),alpha=.10,colour=NA)+geom_line(linewidth=.7)+geom_point(size=1.4)+scale_x_log10(breaks=refsizes,labels=scales::label_number(big.mark=','))+scale_colour_manual(values=cols,breaks=models,name=NULL,labels=c('Crude','Age + sex','Age residual'))+scale_fill_manual(values=cols,guide='none')+scale_linetype_manual(values=c('age-weighted'='solid','uniform'='dashed'),name=NULL,labels=c('Age-weighted','Unweighted'))+labs(title='DISCO',x='Reference size',y='Mortality C-index')+theme_classic(base_size=12)+theme(axis.text.x=element_text(angle=45,hjust=1),plot.title=element_text(face='bold'),legend.position='bottom',legend.text=element_text(size=10))
ph2<-ggplot(ms,aes(refsize,mean,colour=model,fill=model,group=model))+geom_ribbon(aes(ymin=mean-SD,ymax=mean+SD),alpha=.10,colour=NA)+geom_line(linewidth=.7)+geom_point(size=1.4)+scale_x_log10(breaks=refsizes,labels=scales::label_number(big.mark=','))+scale_colour_manual(values=cols,breaks=c('crude','age+sex'),labels=c('Crude','Age + sex'),name=NULL)+scale_fill_manual(values=cols,guide='none')+labs(title='DM',x='Reference size',y='Mortality C-index')+theme_classic(base_size=12)+theme(axis.text.x=element_text(angle=45,hjust=1),plot.title=element_text(face='bold'),legend.position='bottom',legend.text=element_text(size=10))
ggsave(file.path(m,'figures/ED4h_FULL_NESTED50_DISCO_DM.pdf'),ph1+ph2+plot_annotation(tag_levels='a'),width=10,height=4.6,device='pdf')
write.csv(ds,file.path(m,'tables/ED4h_DISCO_summary_42.csv'),row.names=FALSE);write.csv(ms,file.path(m,'tables/ED4h_DM_summary_14.csv'),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(m,'logs/plot_sessionInfo.txt'))
